 NOR-EU NOR-MAC SEA SOU-BRA STH-OPEN|TRA TDC AEG BLA GUL MED NOR-DOL NOR-EU NOR-MAC SEA SOU-CAPE|TRI DGA AEG GUL IND-E IND-EAF IND-S MED NOR-DOL NOR-EU NOR-MAC SOU-ANG SOU-CAPE|TRI FLO AEG MED NOR-EU NOR-MAC|TRI MWY AEG MED NOR-DOL NOR-EU NOR-MAC NRT-OPEN SOU-BRA STH-OPEN|TRI PTC AEG MED NOR-DOL NOR-EU NOR-MAC SOU-BRA STH-OPEN|TRI TDC AEG GUL MED NOR-DOL NOR-EU NOR-MAC SOU-CAPE|TRO DGA GUL IND-E IND-EAF IND-S NOR-DOL NOR-EU NOR-MAC NRW SOU-ANG SOU-CAPE|TRO FLO NEA NOR-EU NOR-MAC NOR-MID NRW|TRO MWY NOR-DOL NOR-EU NOR-MAC NOR-MID NRT-OPEN NRW SOU-BRA STH-OPEN|TRO PTC NOR-DOL NOR-EU NOR-MAC NOR-MID NRW SOU-BRA STH-OPEN|TRO TDC GUL NOR-DOL NOR-EU NOR-MAC NRW SOU-CAPE|TRP DGA GUL IND-E IND-EAF IND-S MED NOR-DOL NOR-EU NOR-MAC SOU-ANG SOU-CAPE|TRP FLO MED NOR-EU NOR-MAC|TRP MWY MED NOR-DOL NOR-EU NOR-MAC NRT-OPEN SOU-BRA STH-OPEN|TRP PTC MED NOR-DOL NOR-EU NOR-MAC SOU-BRA STH-OPEN|TRP TDC GUL MED NOR-DOL NOR-EU NOR-MAC SOU-CAPE|TSU DGA AND EAS IND-E KOR SOA STR TAI|TSU FLO EAS GUL IND-E IND-S JAV KOR NOR-DOL NOR-MAC SOA SOU-ANG SOU-CAPE VIS|TSU MWY EAS KOR NRT-JP NRT-OPEN PHI-JP|TSU PTC EAS KOR NRT-JP NRT-OPEN PHI-JP STH-OPEN|TSU TDC EAS IND-E IND-S JAV KOR SOA SOU-CAPE VIS|TUN DGA GUL IND-E IND-EAF IND-S MED NOR-DOL NOR-EU NOR-MAC SOU-ANG SOU-CAPE|TUN FLO MED NOR-EU NOR-MAC|TUN MWY MED NOR-DOL NOR-EU NOR-MAC NRT-OPEN SOU-BRA STH-OPEN|TUN PTC MED NOR-DOL NOR-EU NOR-MAC SOU-BRA STH-OPEN|TUN TDC GUL MED NOR-DOL NOR-EU NOR-MAC SOU-CAPE|TUR DGA BAL BAY ENG GUL IND-E IND-EAF IND-S NEA NOR-DOL NOR-EU NOR-MAC SOU-ANG SOU-CAPE|TUR FLO BAL NEA NOR-EU NOR-MAC NOR-MID|TUR MWY BAL BAY ENG NEA NOR-DOL NOR-EU NOR-MAC NOR-MID NRT-OPEN SOU-BRA STH-OPEN|TUR PTC BAL BAY ENG NEA NOR-DOL NOR-EU NOR-MAC NOR-MID SOU-BRA STH-OPEN|TUR TDC BAL BAY ENG GUL NEA NOR-DOL NOR-EU NOR-MAC SOU-CAPE|ULS DGA AND EAS IND-E KOR SOA STR TAI|ULS FLO EAS GUL IND-E IND-S JAV KOR NOR-DOL NOR-MAC SOA SOU-ANG SOU-CAPE VIS|ULS MWY KOR NRT-JP NRT-OPEN SFJ|ULS PTC KOR NRT-JP NRT-OPEN SFJ STH-OPEN|ULS TDC EAS IND-E IND-S JAV KOR SOA SOU-CAPE VIS|VAL DGA GUL IND-E IND-EAF IND-S MED NOR-DOL NOR-EU NOR-MAC SOU-ANG SOU-CAPE|VAL FLO MED NOR-EU NOR-MAC|VAL MWY MED NOR-DOL NOR-EU NOR-MAC NRT-OPEN SOU-BRA STH-OPEN|VAL PTC MED NOR-DOL NOR-EU NOR-MAC SOU-BRA STH-OPEN|VAL TDC GUL MED NOR-DOL NOR-EU NOR-MAC SOU-CAPE|VAR DGA BAR GUL IND-E IND-EAF IND-S NOR-DOL NOR-EU NOR-MAC NRW SOU-ANG SOU-CAPE|VAR FLO BAR NOR-EU NOR-ICE NOR-MAC NOR-MID NRW|VAR MWY BAR NOR-DOL NOR-EU NOR-MAC NOR-MID NRT-OPEN NRW SOU-BRA STH-OPEN|VAR PTC BAR NOR-DOL NOR-EU NOR-MAC NOR-MID NRW SOU-BRA STH-OPEN|VAR TDC BAR GUL NOR-DOL NOR-EU NOR-MAC NRW SOU-CAPE|VEN DGA ADR GUL IND-E IND-EAF IND-S ION MED NOR-DOL NOR-EU NOR-MAC SOU-ANG SOU-CAPE|VEN FLO ADR ION MED NOR-EU NOR-MAC|VEN MWY ADR ION MED NOR-DOL NOR-EU NOR-MAC NRT-OPEN SOU-BRA STH-OPEN|VEN PTC ADR ION MED NOR-DOL NOR-EU NOR-MAC SOU-BRA STH-OPEN|VEN TDC ADR GUL ION MED NOR-DOL NOR-EU NOR-MAC SOU-CAPE|VER DGA CAR GCO IND-E IND-EAF IND-S NOR-AM NOR-DOL SOU-ANG SOU-BRA SOU-CAPE|VER FLO GCO NOR-AM NOR-MAC NOR-MID|VER MWY CAR GCO NOR-AM NOR-DOL NRT-OPEN SOU-BRA STH-OPEN|VER PTC CAR GCO NOR-AM NOR-DOL SOU-BRA STH-OPEN|VER TDC CAR GCO NOR-AM NOR-DOL SOU-BRA SOU-CAPE|VIS DGA BAL BAY ENG GUL IND-E IND-EAF IND-S NEA NOR-DOL NOR-EU NOR-MAC SOU-ANG SOU-CAPE|VIS FLO BAL NEA NOR-EU NOR-MAC NOR-MID|VIS MWY BAL BAY ENG NEA NOR-DOL NOR-EU NOR-MAC NOR-MID NRT-OPEN SOU-BRA STH-OPEN|VIS PTC BAL BAY ENG NEA NOR-DOL NOR-EU NOR-MAC NOR-MID SOU-BRA STH-OPEN|VIS TDC BAL BAY ENG GUL NEA NOR-DOL NOR-EU NOR-MAC SOU-CAPE|VLL DGA GUL IND-E IND-EAF IND-S MED NOR-DOL NOR-EU NOR-MAC SOU-ANG SOU-CAPE|VLL FLO MED NOR-EU NOR-MAC|VLL MWY MED NOR-DOL NOR-EU NOR-MAC NRT-OPEN SOU-BRA STH-OPEN|VLL PTC MED NOR-DOL NOR-EU NOR-MAC SOU-BRA STH-OPEN|VLL TDC GUL MED NOR-DOL NOR-EU NOR-MAC SOU-CAPE|VLP DGA IND-E IND-EAF IND-S SOU-CAPE STH-AM STH-OPEN|VLP FLO NOR-DOL NOR-MAC NOR-MID SOU-BRA STH-AM STH-OPEN|VLP MWY NRT-AM NRT-OPEN STH-AM STH-OPEN|VLP PTC STH-AM STH-OPEN|VLP TDC SOU-CAPE STH-AM STH-OPEN|WIL DGA CAR IND-E IND-EAF IND-S NOR-AM NOR-DOL SOU-ANG SOU-BRA SOU-CAPE|WIL FLO CAR NOR-AM NOR-MAC NOR-MID|WIL MWY CAR NOR-AM NOR-DOL NRT-OPEN SOU-BRA STH-OPEN|WIL PTC CAR NOR-AM NOR-DOL SOU-BRA STH-OPEN|WIL TDC CAR NOR-AM NOR-DOL SOU-BRA SOU-CAPE|WLG DGA IND-E IND-S TAS|WLG FLO NOR-DOL NOR-MAC NOR-MID SOU-BRA STH-AM STH-OPEN TAS|WLG MWY NRT-OPEN STH-AM STH-OPEN TAS|WLG PTC STH-AM STH-OPEN TAS|WLG TDC SOU-CAPE STH-AM STH-OPEN TAS|XIA DGA AND IND-E SOA STR TAI|XIA FLO GUL IND-E IND-S JAV NOR-DOL NOR-MAC SOA SOU-ANG SOU-CAPE TAI|XIA MWY EAS NRT-JP NRT-OPEN PHI-JP TAI|XIA PTC NRT-OPEN PHI SOA STH-AM STH-OPEN TAI VIS|XIA TDC IND-E IND-S JAV SOA SOU-CAPE TAI|YEO DGA AND EAS IND-E KOR SOA STR TAI|YEO FLO EAS GUL IND-E IND-S JAV KOR NOR-DOL NOR-MAC SOA SOU-ANG SOU-CAPE TAI|YEO MWY EAS KOR NRT-JP NRT-OPEN PHI-JP|YEO PTC EAS KOR NRT-JP NRT-OPEN PHI-JP STH-OPEN|YEO TDC EAS IND-E IND-S JAV KOR SOA SOU-CAPE TAI|ZAK DGA GUL IND-E IND-EAF IND-S ION MED NOR-DOL NOR-EU NOR-MAC SOU-ANG SOU-CAPE|ZAK FLO ION MED NOR-EU NOR-MAC|ZAK MWY ION MED NOR-DOL NOR-EU NOR-MAC NRT-OPEN SOU-BRA STH-OPEN|ZAK PTC ION MED NOR-DOL NOR-EU NOR-MAC SOU-BRA STH-OPEN|ZAK TDC GUL ION MED NOR-DOL NOR-EU NOR-MAC SOU-CAPE|ZAN DGA IND-E IND-EAF|ZAN FLO GUL IND-EAF IND-S MOZ NOR-DOL NOR-MAC SOU-ANG SOU-CAPE|ZAN MWY IND-E IND-EAF JAV MAK MOL NRT-OPEN PHI VIS|ZAN PTC IND-EAF IND-S MOZ SOU-CAPE STH-OPEN|ZAN TDC IND-EAF IND-S MOZ SOU-CAPE$legs$, '|')) e;
    insert into public.sea_leg_asks (from_port, to_port, wave_min, title_min, zones)
    select a.id, b.id, greatest(q.wave_min, zt.wave_min)::int, greatest(q.title_min, zt.title_min)::int, q.zones
      from legs_h l join public.ports a on a.code = l.f join public.ports b on b.code = l.t
      join public.sea_zones zt on zt.code = public.harbour_zone(b.id)
     cross join lateral (select array_agg(z.code order by z.code) as zones, max(z.wave_min) as wave_min, max(z.title_min) as title_min, count(*) as n
                           from public.sea_zones z where z.code = any (l.z)) q
     where q.n = cardinality(l.z);
    get diagnostics v_asks_h = row_count;
    insert into public.sea_leg_asks (from_port, to_port, wave_min, title_min, zones)
    select n.id, n.id, z.wave_min, z.title_min, array[z.code]
      from new_h n join public.sea_zones z on z.code = public.harbour_zone(n.id);
    get diagnostics v_n_h = row_count;
    v_asks_h := v_asks_h + v_n_h;

    -- ── the harbours' own assert: their rows only ──
    select count(*) into v_harb_h from public.ports p where p.kind = 'HARBOUR';
    if v_asks_h <> 2 * 5 * (v_harb_h - 5) + 20 + 5 then
      raise exception '0409 (harbours) FAIL: % pair row(s) written, % expected (a sea zone of data/sea-legs.json is not in public.sea_zones, or a harbour is missing)', v_asks_h, 2 * 5 * (v_harb_h - 5) + 25;
    end if;
    if exists (select 1 from public.sea_reaches sr where sr.code = any (c_hubs) and (select count(*) from jsonb_object_keys(sr.reaches)) <> (select count(*) from public.sea_reaches) - 1)
       or exists (select 1 from public.sea_reaches sr where sr.code <> all (c_hubs) and (select count(*) from jsonb_object_keys(sr.reaches) k where k = any (c_hubs)) <> 5)
       or exists (select 1 from public.sea_reaches a join public.sea_reaches b on b.code = any (c_hubs) and b.code <> a.code
                   where (a.reaches ->> b.code)::numeric is distinct from (b.reaches ->> a.code)::numeric)
       or exists (select 1 from public.sea_reaches sr join public.ports p on p.id = sr.port_id cross join lateral voyage.water_roadstead(p.lat, p.lon) w
                   where sr.code = any (c_hubs) and (w.lat, w.lon) is distinct from (sr.roadstead_lat, sr.roadstead_lon)) then
      raise exception '0409 (harbours) FAIL: a hub''s row of public.sea_reaches is not whole, not symmetric, or its roadstead is not voyage.water_roadstead''s';
    end if;
    if exists (select 1 from new_h n where (select count(*) from public.port_goods pg where pg.port_id = n.id) <> (select count(*) from public.goods))
       or exists (select 1 from new_h n join public.port_treasury t on t.port_id = n.id where t.ducats <> 0)
       or (select count(*) from public.port_treasury t where t.port_id in (select id from new_h)) <> 5
       or (select count(*) from public.npc_courses c join new_h n on n.id = c.from_port where exists (select 1 from public.npc_courses b where b.from_port = c.to_port and b.to_port = c.from_port)) <> 80 / 2 then
      raise exception '0409 (harbours) FAIL: a hub lacks a market row for a good, holds a purse that is not 0, or a course has no way back';
    end if;
    select coalesce(sum(s.n_tup_ins + s.n_tup_upd + s.n_tup_del), 0) into v_xact1_h
      from pg_stat_xact_user_tables s where s.schemaname = 'public' and s.relname in ('players', 'treasury_flows', 'treasury_daybook', 'ledger');
    if v_xact1_h <> v_xact0_h then
      raise exception '0409 (harbours) FAIL: the harbours wrote % row(s) to players / treasury_flows / treasury_daybook / ledger: no money may move here', v_xact1_h - v_xact0_h;
    end if;
    v_recv := jsonb_build_object('places', v_places_h, 'new_rows', v_newrows_h, 'moved_rows', v_moved_h, 'hauled_rows', v_hauled_h, 'pair_rows', v_asks_h);
  end;

  -- ── 3. THE HUBS, THE ROSTER, THE COLUMN, THE KNOBS ──
  create table public.pirate_hubs (
    port_id        uuid primary key references public.ports(id),
    ground         text not null,
    ground_name    text not null,
    ground_name_ko text not null,
    ships          integer not null check (ships >= 0),
    reach_nm       numeric not null check (reach_nm > 0)
  );
  comment on table public.pirate_hubs is '0409: one row a pirate hub: the ocean it is the haven of (`ground`; the Pacific has two), the SHIPS the owner ordered for it (the hulls of its rows in public.pirate_roster add up to it), and how far by a stored course its ships cruise for a haunt (public.pirate_haunt_of; a ship of a home that is no hub cruises navy_reach_nm). An ocean is where they mostly roam, not a fence. Server-only.';
  alter table public.pirate_hubs enable row level security;
  revoke all on table public.pirate_hubs from public, anon, authenticated;
  create table public.pirate_roster (
    ord           integer primary key check (ord > 1000),
    hub_port      uuid not null references public.pirate_hubs(port_id),
    house         integer not null check (house >= 1),
    house_name    text not null,
    house_name_ko text not null,
    fleet_name    text not null unique,
    fleet_name_ko text not null
  );
  comment on table public.pirate_roster is '0409: THE FLEETS THE PIRATES KEEP BEYOND public.pirate_size(), as data: one row a fleet. `ord` is her public.pirate_ships.ord (above 1000; 0339''s ships are 1 to pirate_size()); her home is `hub_port`; fleets of one (hub_port, house) sail for one house. Her hulls are public.pirate_roster_hulls. Built by public.pirate_commission_fleet, in public.pirate_next_ord''s order. Add, change or delete rows to tune the pirates: a deleted row''s fleet sails home and is laid up (public.pirate_ord_wanted). Server-only.';
  alter table public.pirate_roster enable row level security;
  revoke all on table public.pirate_roster from public, anon, authenticated;
  create table public.pirate_roster_hulls (
    ord   integer not null references public.pirate_roster(ord) on delete cascade,
    class text not null references public.ship_classes(code),
    n     integer not null check (n between 1 and 9),
    primary key (ord, class)
  );
  comment on table public.pirate_roster_hulls is '0409: the hulls of a roster fleet: n ships of a class (public.ship_classes.code). The dearest class is her lead ship. Read when she is built; a later change does not rebuild a fleet that sails. Server-only.';
  alter table public.pirate_roster_hulls enable row level security;
  revoke all on table public.pirate_roster_hulls from public, anon, authenticated;

